<?php $this->layout('default'); use Moves\Services\CmsMedia; use Moves\Support\CmsView as V;
$filters = ['q' => V::queryString('q'), 'kind' => V::queryString('kind')]; $result = CmsMedia::listing($filters, V::queryPage()); ?>
<?php $this->start('actions'); ?><span class="cms-pill"><?= (int) $result['total'] ?> arquivo(s)</span><?php $this->stop(); ?>
<details class="cms-card" <?= $result['total'] === 0 ? 'open' : '' ?>><summary>Enviar arquivo</summary><form method="post" action="/acao/media-upload" enctype="multipart/form-data"><?= V::csrf() ?><div class="cms-form-grid"><?= V::field('Arquivo (JPG, PNG, GIF, WebP ou PDF, até 8 MB)', 'file', '', ['type' => 'file', 'required' => true]) ?><?= V::field('Título', 'title') ?><?= V::field('Texto alternativo', 'alt_text') ?></div><div class="cms-form-end"><button class="cms-btn-primary">Enviar</button></div></form></details>
<section class="cms-list"><?= V::listHead('Biblioteca', 'Selecione para remover em lote', V::searchForm('Buscar arquivo', ['kind' => [$filters['kind'], ['' => 'Todos', 'image' => 'Imagens', 'pdf' => 'PDF'], 'Tipo']])) ?>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhum arquivo na biblioteca.') ?><?php else: ?><form id="media-bulk" method="post" action="/acao/media-delete-bulk" class="cms-bulkbar" data-confirm="Excluir os arquivos selecionados? Os que estão em uso ficam de fora."><?= V::csrf() ?><button class="cms-btn-danger">Remover selecionados</button></form>
<div class="cms-media-grid"><?php foreach ($result['rows'] as $m): $uses = CmsMedia::usage($m); ?><article class="cms-media-item"><div class="cms-media-thumb"><?php if (str_starts_with($m['mime_type'], 'image/')): ?><img src="<?= V::e(CmsMedia::thumb($m)) ?>" alt="<?= V::e($m['alt_text']) ?>" loading="lazy"><?php else: ?><i><?= V::icon('pages') ?></i><?php endif; ?><input type="checkbox" form="media-bulk" name="ids[]" value="<?= (int) $m['id'] ?>" aria-label="Selecionar <?= V::e($m['original_name']) ?>"><?= $uses > 0 ? V::badge('info', 'Em uso') : '<span class="cms-badge cms-badge-free">Livre</span>' ?></div><strong><a href="<?= V::e(CmsMedia::url($m['stored_path'])) ?>" target="_blank" rel="noopener"><?= V::e($m['title'] !== '' ? $m['title'] : $m['original_name']) ?></a></strong><small><?= $m['width'] ? (int) $m['width'] . ' × ' . (int) $m['height'] . ' px · ' : '' ?><?= V::size((int) $m['size_bytes']) ?></small>
<details><summary>Editar</summary><form method="post" action="/acao/media-update"><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $m['id'] ?>"><div class="cms-field"><label>Título<input name="title" value="<?= V::e($m['title']) ?>"></label></div><div class="cms-field"><label>Texto alternativo<input name="alt_text" value="<?= V::e($m['alt_text']) ?>"></label></div><button class="cms-btn">Salvar</button></form></details></article><?php endforeach; ?></div><?= V::pager($result) ?><?php endif; ?></section>
